service.launcher_content:
@echo off
title Open-Melayu 15K
echo ========================================================
echo   Checking Open-Melayu 15K Web Service...
echo ========================================================

netstat -ano | findstr :8766 | findstr LISTENING >nul 2>&1
if %ERRORLEVEL% NEQ 0 (
    echo [*] Starting background server on port 8766...
    start "" "C:\Users\d\AppData\Local\Programs\Python\Python313\pythonw.exe" "C:\Users\d\Documents\open-melayu\app\server.py"
    timeout /t 1 >nul
)

echo [*] Opening Open-Melayu 15K in browser...
start "" "http://127.0.0.1:8766"
exit /b 0

args.CommandLine:
"python -c "
import json, glob, os
files = glob.glob(r'c:\Users\d\Documents\open-melayu\.tmp\codex_staging\worker_*\batch_*.json')
print('Total staging batch files found:', len(files))
harvestable_words = 0
for f in files:
    try:
        with open(f, 'r', encoding='utf-8') as fp:
            data = json.load(fp)
            if isinstance(data, list):
                for entry in data:
                    w = entry.get('headword', {}).get('word')
                    if w and entry.get('senses') and entry.get('morphology') and entry.get('etymology'):
                        harvestable_words += 1
    except Exception:
        pass
print('Harvestable valid words in staging:', harvestable_words)
""

"python -c "
import json, glob, os
files = glob.glob(r'c:\Users\d\Documents\open-melayu\.tmp\codex_staging\worker_*\batch_*.json')
has_jawi = 0
missing_jawi = []
for f in files:
    try:
        with open(f, 'r', encoding='utf-8') as fp:
            data = json.load(fp)
            if isinstance(data, list):
                for entry in data:
                    hw = entry.get('headword', {})
                    w = hw.get('word')
                    if hw.get('jawi'):
                        has_jawi += 1
                    else:
                        missing_jawi.append(w)
    except Exception:
        pass
print('Has Jawi:', has_jawi)
print('Missing Jawi count:', len(missing_jawi))
print('Sample missing Jawi:', missing_jawi[:20])
""
